def backfill_interviews(apps, schema_editor):
    """Applications that already have an interview time get an Interview record, so they show in the calendar."""
    Application = apps.get_model('api', 'Application')
    Interview = apps.get_model('api', 'Interview')
    rows = Application.objects.filter(status='interview_scheduled', interview_date__isnull=False)
    for app in rows.select_related('candidate', 'job'):
        owner_id = app.candidate.owner_id
        if owner_id is None:
            continue
        Interview.objects.get_or_create(
            application=app,
            defaults={
                'owner_id': owner_id, 'candidate_id': app.candidate_id, 'job_id': app.job_id,
                'scheduled_at': app.interview_date, 'platform': 'Google Meet',
                'link': 'meet.google.com/recruitment-' + app.candidate.name.lower().replace(' ', '-'),
                'status': 'scheduled', 'history': [],
            },
        )


